import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as l}from"./chunks/image-032._eBok2xC.js";import{_ as i,o,c as s,a3 as r}from"./chunks/framework.DdpBa4_E.js";const a="/ReadBooks/assets/image-034.gvBNOg9g.gif",u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/55-结和第四十三.md","filePath":"books/yan-tie-lun/55-结和第四十三.md","lastUpdated":1794316978000}'),_={name:"books/yan-tie-lun/55-结和第四十三.md"};function n(e,t,g,m,d,c){return o(),s("div",null,[...t[0]||(t[0]=[r('<p>结和第四十三 【题解】</p><p>本篇就汉家与匈奴是和是战的问题展开探讨。大夫认为，历史事实证明汉家一度奉行的和亲政策是不成功的，因为匈奴根本没有诚意与汉家修好，所以征讨匈奴是朝廷唯一的选择，他充分肯定了汉武帝征讨匈奴的历史功绩，并从长远角度，主张汉家必须继续伐胡，为后代根除祸患。文学则主张汉家与匈奴修好，肯定和亲政策，反对汉家兴师动众去征讨北方无用之地，认为伐胡会导致民众疲惫，严重者会造成国家覆灭的恶果。从双方观点来看，大夫与文学各有偏颇：大夫看到了伐胡在一定历史时期内的必要性与合理性，却没有考虑到汉家在几十年伐胡之后已经国穷民疲，当时的国家要务是与民休息；文学看到了人民为伐胡所作出的巨大牺牲，在汉昭帝时代他们倡导朝廷休兵，这无疑反映了广大人民的要求，但是他们连此前汉武帝伐胡业绩一并否定，只知道一味地讲修文德怀柔，这反映了他们的迂腐和不知变通。</p><p>大夫曰：“汉兴以来，修好结和亲[(1)]，所聘遗单于者甚厚[(2)]；然不纪重质厚赂之故改节[(3)]，而暴害滋甚[(4)]。先帝睹其可以武折[(5)]，而不可以德怀，故广将帅，招奋击[(6)]，以诛厥罪；功勋粲然[(7)]，著于海内，藏于记府[(8)]，何命‘亡十获一’乎[(9)]？夫偷安者后危，虑近者忧迩，贤者离俗，智士权行[(10)]，君子所虑，众庶疑焉。故民可与观成[(11)]，不可与图始[(12)]。此有司所独见，而文学所不睹。”</p><p>【注释】</p><p>[(1)]和亲：讲和结亲。这是汉初刘敬给刘邦提出的对待匈奴的策略：将汉家公主嫁给匈奴单于，生下的孩子就是汉家天子的外孙，天下没有外孙反对外公的道理。刘邦采纳了刘敬的建议。此后将中国与少数民族缔结姻亲的举措称为和亲。</p><p>[(2)]聘：以礼物订婚，此处指陪嫁财物。遗（wèi）：赠送。</p><p>[(3)]纪：通“记”，念记。重质：庄重的盟约。厚赂：优厚的财物。改节：改变行为节操。</p><p>[(4)]暴害：暴力侵害。滋甚：越来越厉害。</p><p>[(5)]先帝：汉武帝。武折：武力折服。</p><p>[(6)]奋击：勇敢的士兵。</p><p>[(7)]粲然：显著的样子。</p><p>[(8)]记府：国家档案馆。</p><p>[(9)]命：名，说。</p><p>[(10)]权行：权变。</p><p>[(11)]观成：看到成功。《史记·商君列传》：“民不可与虑始，而可与乐成。”</p><p>[(12)]图始：谋划开始。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“汉家建国以来，与匈奴修好讲和，缔结姻亲，给匈奴单于的陪嫁礼物和赠送金钱财物非常丰厚；但是匈奴不念记与汉家庄重的盟约以及汉家赠送的厚礼，不改变侵扰行为，以暴力侵害中国边境越来越厉害。已故武帝认识到，对待匈奴只能以武力折服，而不能以仁德怀柔，因此广泛选派将帅，征召勇敢的士兵，来诛讨匈奴侵扰中国的罪行；武帝伐胡的功勋卓著，为海内所著称，有关记功文献收藏在国家档案馆，怎么能说‘伤亡十个获取一个’呢？苟且偷安的人日后危险，只考虑眼前，忧患很快到来，贤明的人脱离世俗，智慧的人善于权变，君子所考虑的问题，普通庶民总是疑惑。因此民众可以和他们一起看到成功，但不能与他们图谋开始。这是主管官员个人的独到见识，是你们文学认识不到的。”</p><p>文学曰：“往者，匈奴结和亲，诸夷纳贡，即君臣外内相信，无胡、越之患。当此之时，上求寡而易赡，民安乐而无事，耕田而食，桑麻而衣，家有数年之稸[(1)]，县官余货财，闾里耆老[(2)]，咸及其泽[(3)]。自是之后，退文任武，苦师劳众，以略无用之地[(4)]，立郡沙石之间[(5)]，民不能自守，发屯乘城[(6)]，挽辇而赡之[(7)]。愚窃见其亡，不睹其成。”</p><p>【注释】</p><p>[(1)]稸：同“蓄”。</p><p>[(2)]耆（qí）：六十曰耆。</p><p>[(3)]咸：都。及：蒙受。泽：恩泽。</p><p>[(4)]略：征伐。</p><p>[(5)]立郡沙石之间：指汉武帝在边塞沙漠之地设置武威、酒泉、张掖、敦煌、朔方等郡。</p><p>[(6)]发屯：派兵驻守。乘城：登城。</p><p>[(7)]挽辇：拉车。赡：补充给养。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“以前，汉家与匈奴缔结和亲，其他周边蛮夷邦国向汉家纳贡称臣，君臣上下、国外国内都彼此相信，没有胡、越的祸患。在那个时候，朝廷索求很少且容易充足，民众安居乐业，相安无事，依靠种田吃饭，通过种植桑麻穿衣，老百姓家中有数年的积蓄，朝廷有富余的货财，连乡里那些老人，都蒙受朝廷的恩泽。从那以后，朝廷不用文治而任武功，兴师动众，来征伐西北边塞无用之地，在沙漠里设郡，民众不能自己守卫，只好派兵屯驻，登城守望，通过拉车来补充给养。我私下只看到损失，没有看到成功。”</p><p>大夫曰：“匈奴以虚名市于汉[(1)]，而实不从；数为蛮、貊所绐[(2)]，不痛之，何故也？高皇帝仗剑定九州[(3)]；今以九州而不行于匈奴[(4)]。闾里常民，尚有枭散[(5)]，况万里之主与小国之匈奴乎？夫以天下之力勤何不摧[(6)]？以天下之士民何不服？今有帝名，而威不信于长城之外[(7)]，反赂遗而尚踞敖[(8)]，此五帝所不忍[(9)]，三王所毕怒也[(10)]。”</p><p>【注释】</p><p>[(1)]虚名：虚假名义。市：做交易。</p><p>[(2)]蛮貊：蛮荒落后地区，此处指匈奴。绐（dài）：欺骗。</p><p>[(3)]高皇帝仗剑定九州：《史记·高祖本纪》载有“吾以布衣持三尺剑取天下”之语，为大夫所本。</p><p>[(4)]不行于匈奴：指汉家政令不能推行到匈奴。</p><p>[(5)]枭（xiāo）散：古代博戏中的两种棋子，主棋为枭，余为散棋。</p><p>[(6)]力勤：力量。摧：原作“权”，据卢文弨说校改。</p><p>[(7)]威不信于长城之外：原作“威不信长城之外”，据王先谦说补“于”字。信，通“伸”。</p><p>[(8)]赂遗：赠送财物。尚：助长。踞敖：傲慢。踞，通“倨”。敖，通“傲”。</p><p>[(9)]五帝：黄帝、颛顼、帝喾、尧、舜。</p><p>[(10)]三王：夏禹、商汤、周文王。此外还有其他说法。毕怒：必定愤怒。毕，一本作“必”。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“匈奴以虚假名义与汉家做交易，实际上并不顺从汉家；汉家屡次被这些蛮夷所欺骗，你们对此不感到痛恨，这是什么缘故呢？从前高祖皇帝手持三尺剑定天下，如今汉家政令仅限于中国九州，而不能推行到匈奴。乡里普通民众，尚且有主次之分，何况是中国万里江山之主与小国匈奴呢？举中国之力，何坚不摧？凭借中国全体将士民众，何人不服？如今中国天子虽然拥有帝名，但威望却不能伸张到长城之外，反而赠送匈奴财物，助长他们的傲慢，这是五帝所不能容忍、三王必定感到愤怒的事情。”</p><p>文学曰：“汤事夏而卒服之[(1)]，周事殷而卒灭之。故以大御小者王[(2)]，以强凌弱者亡。圣人不困其众以兼国[(3)]，良御不困其马以兼道[(4)]。故造父之御不失和[(5)]，圣人之治不倍德[(6)]。秦摄利衔以御宇内[(7)]，执修棰以笞八极[(8)]，骖服以罢[(9)]，而鞭策愈加，故有倾衔遗棰之变[(10)]。士民非不众，力勤非不多也，皆内倍外附而莫为用。此高皇帝所以仗剑而取天下也。夫两主好合[(11)]，内外交通[(12)]，天下安宁，世世无患，士民何事？三王何怒焉？”</p><p>【注释】</p><p>[(1)]服：征服。</p><p>[(2)]以大御小：周文王时期，三分天下有其二，仍然侍奉殷朝。御，侍奉。</p><p>[(3)]兼国：兼并他国。</p><p>[(4)]兼道：加倍赶路。</p><p>[(5)]造父：西周穆王时期最善驾车的人，曾载穆王周游天下。和：和谐，协调。</p><p>[(6)]倍：通“背”。</p><p>[(7)]摄：操持。利：便利。衔：马嚼子。原作“衡”，据王先谦说校改。</p><p>[(8)]修棰：长鞭。八极：八方。</p><p>[(9)]骖服：驾车的马。居中驾辕的马称为服，位于两侧的马称为骖。以：通“已”。罢：同“疲”。</p><p>[(10)]倾衔遗棰：马匹倒仆，丢失马鞭。衔，原作“衡”，据王先谦说校改。</p><p>[(11)]两主：汉家天子和匈奴单于。好合：和好。</p><p>[(12)]交通：交流。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“汤侍奉夏朝而最终征服了夏朝，周侍奉殷朝而最终消灭了殷朝。因此，以势力强大的身份侍奉弱小王朝的最终称王天下，以强国地位欺凌弱国的政权最终灭亡。圣明的君主不会困乏一国之众去兼并他国，优秀的车夫不会困乏马匹来加倍赶路。因而造父驾车不失和谐，圣君治国不背仁德。秦王朝攥紧便利的马嚼来统治天下，手执长鞭抽打八方，驾车的马匹早已疲惫不堪，可是鞭子仍然抽打得越来越厉害，因此才有马匹倒仆、马鞭丢失的变故。秦王朝的士兵民众不可谓不众，力量不可谓不多，但民众都内叛秦朝外附诸侯，没有人肯为秦朝所用。这就是高祖皇帝仗剑夺取天下的原因啊。汉家天子与匈奴单于和好，中国与匈奴互通有无，天下晏然安宁，世世代代没有战争祸患，这样的话士兵民众哪有什么战事？三王又能有什么愤怒呢？”</p><p>大夫曰：“伯翳之始封秦[(1)]，地为七十里。穆公开霸[(2)]，孝公广业[(3)]。自卑至上，自小至大。故先祖基之[(4)]，子孙成之[(5)]。轩辕战涿鹿[(6)]，杀两皞、蚩尤而为帝[(7)]，汤、武伐夏、商，诛桀、纣而为王。黄帝以战成功，汤、武以伐成孝[(8)]。故手足之勤，腹肠之养也[(9)]。当世之务，后世之利也。今四夷内侵，不攘[(10)]，万世必有长患。先帝兴义兵以诛强暴，东灭朝鲜，西定冉、</p><p><img src="'+l+'" alt="" loading="lazy"></p><p>，南擒百越，北挫强胡，追匈奴以广北州[(11)]，汤、武之举，蚩尤之兵也[(12)]。故圣主斥地[(13)]，非私其利，用兵，非徒奋怒也[(14)]，所以匡难辟害[(15)]，以为黎民远虑。”</p><p>【注释】</p><p>[(1)]伯翳（yì）之始封秦：《史记·秦本纪》载：“于是孝王曰：‘昔伯翳为舜主畜，畜多息，故有土，赐姓嬴。今其后世亦为朕息马，朕其分土为附庸。’邑之秦，使复续嬴氏祀，号曰秦嬴。”伯翳，又作“伯益”、“大费”，秦人始祖。</p><p>[(2)]穆公：秦穆公，春秋秦国君主，嬴姓，赵氏，名任好，史载称霸西戎，为春秋五霸之一。</p><p>[(3)]孝公：战国时期秦国君主，名渠梁，在位期间重用商鞅实行变法，奖励耕战，为秦国富强打下基础。广业：拓展强国大业。</p><p>[(4)]基之：打下基础。</p><p>[(5)]成之：最后完成。</p><p>[(6)]轩辕战涿鹿：《史记·五帝本纪》载：“蚩尤作乱，不用帝命。于是黄帝乃征师诸侯，与蚩尤战于涿鹿之野，遂禽杀蚩尤。而诸侯咸尊轩辕为天子，伐神农氏，是为黄帝。”轩辕，黄帝之名。</p><p>[(7)]两皞：太皞、少皞。史载黄帝擒蚩尤，不闻黄帝诛太皞、少皞之事。两皞，原作“两曎”，据王利器说校改。</p><p>[(8)]汤、武以伐成孝：《史记·周本纪》载：“九年，武王上祭于毕。东观兵，至于盟津。以文王为木主，载以车，中军。武王自称太子发，言奉文王以伐，不敢自专。”商汤以伐成孝之事未闻。成孝，成就孝的名声。</p><p>[(9)]手足之勤，腹肠之养：手足的勤劳是为了奉养腹肠。</p><p>[(10)]攘：排斥，排除。</p><p>[(11)]追匈奴以广北州：此句之上原有“李牧”二字，据王先谦说校删。广北州，拓广北方边地。</p><p>[(12)]蚩尤之兵：意谓汉家征讨匈奴如同黄帝伐蚩尤的战役。一说，汉人以蚩尤作为善于用兵的典型，故将蚩尤与汤武相提并论。</p><p>[(13)]斥地：开拓疆域。</p><p>[(14)]奋怒：发泄愤怒。</p><p>[(15)]匡难：匡救危难。辟：通“避”。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“秦人始祖伯翳最初封于秦地的时候，土地面积仅为七十里。春秋秦穆公开创秦国霸业，战国秦孝公拓广霸业。秦国地位从低到高，势力从小到大。因而先祖奠定基业，到子孙取得最后成功。轩辕黄帝战于涿鹿，杀死太皞、少皞和蚩尤，成为帝王，商汤伐夏，武王伐商，诛讨夏桀、殷纣王而成为帝王。黄帝依靠战争获得成功，商汤和周武王通过征伐而成就孝道。所以，手足的勤劳是为了奉养腹肠。当代人的战事，可以成为后人的利益。如今四夷内侵中国，如果不外攘四夷，那么后代万世必定有长久祸患。已故武帝发动正义之师，来诛讨强暴的四夷，东边消灭朝鲜，西边平定冉</p><p><img src="'+l+'" alt="" loading="lazy"></p><p>，南边讨平百越，北边挫败强大的匈奴，追逐匈奴，拓广北边的疆域，这是类似于商汤伐桀、武王伐纣的举动，类似于黄帝擒蚩尤的战役。因而圣明君主开疆拓土，并不是为了私利，对外用兵，也不是仅仅为了发泄愤怒，而是为了匡救危难，远避祸害，以此为黎民百姓作长远的考虑。”</p><p>文学曰：“秦南禽劲越[(1)]，北却强胡，竭中国以役四夷[(2)]，人罢极而主不恤[(3)]，国内溃而上不知；是以一夫倡而天下和[(4)]，兵破陈涉，地夺诸侯，何嗣之所利[(5)]？《诗》云：‘雍雍鸣</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>，旭日始旦。’[(6)]登得前利[(7)]，不念后咎[(8)]。故吴王知伐齐之便[(9)]，不知干遂之患[(10)]。秦知进取之利，而不知鸿门之难[(11)]。是知一而不知十也。周谨小而得大[(12)]，秦欲大而亡小[(13)]。语曰：‘前车覆，后车戒。’[(14)]‘殷鉴不远，在夏后之世’矣[(15)]。”</p><p>【注释】</p><p>[(1)]禽：同“擒”。劲：强劲。</p><p>[(2)]役：兵役，此处用做动词，征讨。</p><p>[(3)]人：老百姓。罢：同“疲”。</p><p>[(4)]一夫：陈涉。倡：首倡。</p><p>[(5)]嗣：继嗣，后代子孙。</p><p>[(6)]雍雍鸣</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>（ɡān），旭日始旦：见于《诗经·邶风·匏有苦叶》。雍雍，雁鸣声，今本作“雝雝”。</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>，即“雁”。《毛诗》作“雁”，三家诗作“</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>”。旦，日出，天明。</p><p>[(7)]登得：贪得。前利：眼前利益。</p><p>[(8)]后咎：后来的危害。</p><p>[(9)]吴王知伐齐之便：据《国语·吴语》记载，吴王夫差不听伍子胥之谏，执意要北上伐齐。</p><p>[(10)]干遂之患：《史记·苏秦列传》载：“臣闻越王句践战敝卒三千人，禽夫差于干遂。”干遂，一作“干隧”。</p><p>[(11)]鸿门之难：项羽入关后，在鸿门设宴招待刘邦，这标志着江山易主。</p><p>[(12)]周谨小而得大：周国谨慎小心而得天下。</p><p>[(13)]秦欲大而亡小：秦朝欲望太大，结果亡于小民之手。</p><p>[(14)]前车覆，后车戒：前车倾覆，后车戒慎。</p><p>[(15)]殷鉴不远，在夏后之世：见于《诗经·大雅·荡》。鉴，镜子。夏后，夏君，指夏桀。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“秦王朝在南边平定强越，在北边驱逐匈奴，竭尽中国之力来征讨四夷，民众疲惫至极而君主不加体恤，国内已经崩溃而皇上却不知情；因此，一介民伕陈涉首倡而天下响应，秦兵被陈涉击破，秦国土地被山东诸侯侵夺，这对秦王子孙有什么好处？《诗经·邶风·瓠有苦叶》说：‘鸿雁雍雍鸣，旭日始东升。’贪得眼前利益，不念及后来灾难。因此吴王夫差只知道北伐齐国的便利，没有料到干遂的灭顶之灾。秦朝只知道进攻夺取的好处，而没有想到鸿门宴上的江山新主。这是只知其一，不知其十啊。周国谨慎小心而得天下，秦朝欲望太大而亡于小民之手。俗语说：‘前面车子倾覆了，后面车子就要戒慎。’‘殷朝的镜子不远，就在夏后桀的时代’。”</p>',115)])])}const k=i(_,[["render",n]]);export{u as __pageData,k as default};
